import { createPublicClient, http, encodeAbiParameters, parseAbiParameters, encodeFunctionData } from "viem";
import { baseSepolia } from "viem/chains";
const client = createPublicClient({ chain: baseSepolia, transport: http("https://sepolia.base.org") });
async function main() {
  const router = "0x8B844f885672f333Bc0042cB669255f93a4C1E6b";
  
  const abi = parseAbiParameters("address, uint256, uint256, bytes, bool");
  // Try passing a completely valid path but different token.
  // Wait, the router could revert with SliceOutOfBounds if it expects a DIFFERENT ABI encoding!
  // Let's just simulate the router directly using eth_call.
  const data = "" as any;
  try {
    await client.call({
      to: router,
      data,
      account: "0x8b6FB665ee47226e53C70be1E9d43DbD7b886d59"
    });
  } catch(e) {
    console.log(e.message);
  }
}
main();
